import numpy as np

def feature(job, loads, past_jobs, jobs_left):
    """Signed slack: (mean_load - loads)/scale times (2*tiny - 1), tiny = job/(job+typ)."""
    m = len(loads)
    mean_load = float(np.mean(loads))
    scale = mean_load if mean_load > 0 else 1.0
    if len(past_jobs) > 0:
        typ = float(np.median(past_jobs))
    else:
        typ = job if job > 0 else 1.0
    tiny = job / (job + typ + 1e-9)
    return (mean_load - loads) / scale * (2.0 * tiny - 1.0)

import numpy as np

def feature(job, loads, past_jobs, jobs_left):
    """Negative tiny-job gate on machines whose post-assignment load exceeds the 0.9-quantile of past jobs."""
    if past_jobs.size == 0:
        return np.zeros(loads.shape[0], dtype=float)
    Q = float(np.quantile(past_jobs, 0.9))
    if Q <= 0.0:
        return np.zeros(loads.shape[0], dtype=float)
    ratio = job / (0.25 * Q)
    ratio = min(ratio, 1e6)
    g = 1.0 / (1.0 + ratio ** 4)
    return (-g * (loads + job > Q)).astype(float)

import numpy as np

def feature(job, loads, past_jobs, jobs_left):
    """Gated tiny-job packing: tiny-dominated history scores machines whose post-load stays under the current max load, higher for fuller machines."""
    if past_jobs.size < 5:
        return np.zeros(loads.shape[0])
    Q = np.quantile(past_jobs, 0.9)
    if Q <= 0:
        return np.zeros(loads.shape[0])
    tiny_frac = np.mean(past_jobs <= 0.25 * Q)
    g = 1.0 / (1.0 + ((1.0 - tiny_frac) / 0.2) ** 4)
    C = max(np.max(loads), job)
    if C <= 0:
        return np.zeros(loads.shape[0])
    post = loads + job
    diff = (post - C) / C
    base = np.where(post <= C, diff, -2.0 - diff)
    return g * base

import numpy as np

def feature(job, loads, past_jobs, jobs_left):
    """One-sided fill: reward machines whose post-assignment load stays at or below a history-derived ceiling C = mean(past)+1.5*std(past), gated by a smooth term in the job's size relative to C."""
    if past_jobs.size < 5:
        return np.zeros(loads.shape[0])
    C = max(float(np.mean(past_jobs)) + 1.5 * float(np.std(past_jobs)), float(job))
    post = loads + job
    base = np.where(post <= C, (post - C) / C, -2.0 - (post - C) / C)
    g = 1.0 / (1.0 + min(float(job) / (0.25 * C), 1e6) ** 4)
    return g * base
